const response = $input.item.json;
const payments = response.data || [];
const today = new Date();

const overdue = payments.filter(p => {
  if (!p.tanggal_jatuh_tempo) return false;
  return new Date(p.tanggal_jatuh_tempo) < today && p.status !== 'lunas';
});

console.log(`Found ${overdue.length} overdue payments`);

return overdue.map(p => ({
  json: {
    pembayaran_id: p.id,
    nama_siswa: p.siswa?.nama || 'Siswa',
    jenis: p.jenis_pembayaran,
    nominal: new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(p.nominal),
    hari_terlambat: Math.floor((today - new Date(p.tanggal_jatuh_tempo)) / (1000 * 60 * 60 * 24)),
    kode_va: p.kode_va,
    fcm_token_ortu: p.siswa?.orang_tua_list?.[0]?.user?.fcm_token
  }
}));

